      ...src,
      loadId: replacementLoad.id,
      groupId: replacementLoad.groupId,
      teacherId: replacementLoad.teacherId,
      subjectId: replacementLoad.subjectId,
      typeId: replacementLoad.typeId,
      subgroup: Number(replacementLoad.subgroup) || 0,
