  const out = {};
  for (const load of (loads || [])) {
    if (!load?.id) continue;
    const entry = {
      weeklyPairs: { ...(load.weeklyPairs || {}) },
      weekPattern: "perWeek",
      graphMode: load.graphMode || "manual",
      graphLocked: !!load.graphLocked,
    };
    out[String(load.id)] = entry;
    const sig = graphPersistenceSignature(load);
    if (sig) out[`sig:${sig}`] = entry;
  }
