  // пользователь может переключиться на «все недели».
  const [candidateWeekFilter, setCandidateWeekFilter] = useState("");
  const [inspecting, setInspecting] = useState(null); // instId for filled-cell modal
  const [confirmPlace, setConfirmPlace] = useState(null); // {instId, day, period, roomId, teacherName}
  const [roomPicker, setRoomPicker] = useState(null); // {instId, day, period, addSecond?}
  const [roomSearch, setRoomSearch] = useState("");
  // v1822: when a manually selected room is occupied, keep the primary room picker
