  const [roomReassign, setRoomReassign] = useState(null); // {targetRoomId, occupantInstId, occupantIds[]}
  const [roomReassignSearch, setRoomReassignSearch] = useState("");
  useEffect(() => { if (!roomPicker) { setRoomReassign(null); setRoomReassignSearch(""); } }, [!!roomPicker]);
  const [subgroupAdder, setSubgroupAdder] = useState(null); // {anchorInstId, day, period}
  const [streamGroupAdder, setStreamGroupAdder] = useState(null); // {anchorInstId, day, period}
