  const [practiceRoomPicker, setPracticeRoomPicker] = useState(null); // {practiceId,date,period}
  const [scheduleEventEditor, setScheduleEventEditor] = useState(null); // non-educational event
  const [filterSpec, setFilterSpec] = useState("");
  // v1831: aggregated views are intentionally filtered before rendering.
