  const [allRoomsFilter, setAllRoomsFilter] = useState(""); // computer | large | medium | small | __all
  const [allGroupsStreamFilter, setAllGroupsStreamFilter] = useState(""); // group.scheduleStream | __none | __all
  // v1861: do not render the entire staff table just by opening its tab.
  const [allTeachersDepartment, setAllTeachersDepartment] = useState("");
  const [allTeachersLetter, setAllTeachersLetter] = useState("");
  const [allTeachersQuery, setAllTeachersQuery] = useState("");
  const [allTeachersPage, setAllTeachersPage] = useState(0);
  const [manualError, setManualError] = useState("");
  // v1836: hide an explicitly purged off-graph row immediately. The unplaced
