  const [offGraphOccurrencePurgePendingKeys, setOffGraphOccurrencePurgePendingKeys] = useState(() => new Set());
  const offGraphStructuralRefreshRef = useRef(null);
  // v1826: placed-lesson drag id lives in a ref.  Updating React state on every
