  // all 15–20k rows. Keep those structural indices memoized across assignment-only
  // moves; their source references do not change on a normal drag.
  const rawScheduleInstById = useMemo(() => new Map((rawSched?.instances || []).map((x)=>[String(x?.instId || ""), x])), [rawSched?.instances]);
  const rawScheduleLockedSet = useMemo(() => new Set((rawSched?.locked || []).map(String)), [rawSched?.locked]);
  const rawScheduleUnplacedSet = useMemo(() => new Set((rawSched?.unplaced || []).map(String)), [rawSched?.unplaced]);

  // v1885 PERF: after the first optimistic drag `rawSchedLocalRef.current` is a
