            loads: groupScopedSave ? rowsForGroupClient(baseForSchedule.loads || [], scheduleGroupId) : (baseForSchedule.loads || []),
            groupDayBlocks: groupScopedSave ? rowsForGroupClient(baseForSchedule.groupDayBlocks || [], scheduleGroupId) : (baseForSchedule.groupDayBlocks || {}),
            groupSlotBlocks: groupScopedSave ? rowsForGroupClient(baseForSchedule.groupSlotBlocks || [], scheduleGroupId) : (baseForSchedule.groupSlotBlocks || {}),
            groupDayFreezes: groupScopedSave ? rowsForGroupClient(baseForSchedule.groupDayFreezes || [], scheduleGroupId) : (baseForSchedule.groupDayFreezes || {}),
